function u(n){if(n==null)return"—";const t=new Date(String(n));if(Number.isNaN(t.getTime()))return String(n);const r=e=>String(e).padStart(2,"0");return`${t.getFullYear()}-${r(t.getMonth()+1)}-${r(t.getDate())} ${r(t.getHours())}:${r(t.getMinutes())}:${r(t.getSeconds())}`}function i(n,t=0){const r=Number(n);return Number.isFinite(r)?r:t}function s(n,t){const r=i(n),e=i(t);return e<=0?"—":`${(r/e*100).toFixed(1)}%`}function o(n){return Array.isArray(n)?n.map(t=>String(t)):typeof n=="string"&&n.length>0?[n]:[]}function a(n){const t=i(n);return t>0?`+${t}`:String(t)}function c(n){if(n==null)return"";try{return JSON.stringify(n,null,2)??""}catch{return String(n)}}function f(n){const t=String(n??"");return t==="create"||t==="unban"?"success":t==="update"?"info":t==="delete"||t==="ban"?"error":t==="adjust_coins"?"warning":"default"}export{f as a,c as b,u as f,o as n,s as p,a as s,i as t};
